<script setup>
import { Head, useForm } from '@inertiajs/vue3';
import { ref } from 'vue';
import HrmsLayout from '@/Layouts/HrmsLayout.vue';
import HrmsStatus from '@/Components/HrmsStatus.vue';
const props = defineProps({ runs:Array, slips:Array, canManage:Boolean });
const selected = ref(props.runs?.[0] || null);
const now = new Date();
const form = useForm({ year:now.getFullYear(), month:now.getMonth()+1 });
const calculate = () => form.post(route('payroll.calculate'));
const approve = run => { if(confirm('اعتماد هذه الدورة ونشر قسائم الرواتب؟')) useForm({}).post(route('payroll.approve',run.id)); };
const money = (value,currency='SAR') => new Intl.NumberFormat('ar-SA',{style:'currency',currency}).format(Number(value || 0));
</script>
<template><Head title="الرواتب" /><HrmsLayout title="الرواتب والقسائم" subtitle="حساب الدورة الشهرية ومراجعة القسائم المنشورة.">
    <div v-if="canManage" class="grid gap-6 xl:grid-cols-[1fr_1.7fr]"><section class="panel p-5"><h2 class="text-lg font-bold text-[#1F3A5F]">احتساب دورة جديدة</h2><p class="mt-2 text-sm leading-6 text-slate-500">يعتمد الحساب على الراتب المسجل والبدلات والاستقطاعات والحضور والإجازات غير المدفوعة.</p><form class="mt-5 flex flex-wrap items-end gap-3" @submit.prevent="calculate"><div><label class="label" for="year">السنة</label><input id="year" v-model.number="form.year" type="number" min="2020" max="2100" class="field w-28"></div><div><label class="label" for="month">الشهر</label><select id="month" v-model.number="form.month" class="field w-32"><option v-for="m in 12" :key="m" :value="m">{{ m }}</option></select></div><button class="btn-primary" :disabled="form.processing">{{ form.processing ? 'جارٍ الحساب…' : 'احتساب الرواتب' }}</button></form><p v-if="form.errors.month" class="error">{{ form.errors.month }}</p></section>
        <section class="panel overflow-hidden"><div class="border-b border-slate-100 px-5 py-4"><h2 class="text-lg font-bold text-[#1F3A5F]">الدورات الأخيرة</h2></div><div v-for="run in runs" :key="run.id" class="flex flex-wrap items-center justify-between gap-3 border-b border-slate-100 px-5 py-4 last:border-0"><div><button class="font-semibold text-[#1F3A5F] hover:underline" @click="selected=run">{{ run.period?.month }}/{{ run.period?.year }} · الإصدار {{ run.revision }}</button><p class="mt-1 text-xs text-slate-500">{{ run.entries?.length }} قسيمة · {{ money(run.entries?.reduce((sum,e)=>sum+Number(e.net_amount),0)) }}</p></div><div class="flex items-center gap-2"><HrmsStatus :value="run.status" /><button v-if="run.status==='calculated'" class="btn-secondary" @click="approve(run)">اعتماد</button></div></div><p v-if="!runs.length" class="p-6 text-sm text-slate-500">لم تُحسب أي دورة بعد.</p></section></div>
    <section v-if="selected && canManage" class="panel mt-6 overflow-hidden"><div class="border-b border-slate-100 px-5 py-4"><h2 class="text-lg font-bold text-[#1F3A5F]">تفاصيل دورة {{ selected.period?.month }}/{{ selected.period?.year }}</h2></div><div class="overflow-x-auto"><table class="w-full min-w-[620px] text-right"><thead class="table-head"><tr><th class="px-4 py-3">الموظف</th><th class="px-4 py-3">الأساسي</th><th class="px-4 py-3">البدلات</th><th class="px-4 py-3">الاستقطاعات</th><th class="px-4 py-3">الصافي</th></tr></thead><tbody><tr v-for="entry in selected.entries" :key="entry.id"><td class="table-cell font-semibold">{{ entry.employee?.first_name }} {{ entry.employee?.last_name }}</td><td class="table-cell">{{ money(entry.base_amount,entry.currency) }}</td><td class="table-cell">{{ money(entry.allowance_total,entry.currency) }}</td><td class="table-cell">{{ money(entry.deduction_total,entry.currency) }}</td><td class="table-cell font-bold text-teal-800">{{ money(entry.net_amount,entry.currency) }}</td></tr></tbody></table></div></section>
    <section class="panel mt-6 overflow-hidden"><div class="border-b border-slate-100 px-5 py-4"><h2 class="text-lg font-bold text-[#1F3A5F]">قسائم راتبي</h2></div><div v-for="slip in slips" :key="slip.id" class="flex flex-wrap items-center justify-between gap-2 border-b border-slate-100 px-5 py-4 last:border-0"><div><div class="font-semibold">{{ slip.run?.period?.month }}/{{ slip.run?.period?.year }}</div><p class="mt-1 text-xs text-slate-500">صافي الراتب {{ money(slip.net_amount,slip.currency) }}</p></div><div class="flex gap-2"><a :href="route('payroll.slip',slip.id)" target="_blank" rel="noopener" class="btn-secondary">عرض / طباعة</a><a :href="route('payroll.download',slip.id)" class="btn-secondary">تنزيل القسيمة</a></div></div><p v-if="!slips.length" class="p-6 text-sm text-slate-500">ستظهر قسائمك هنا بعد اعتمادها ونشرها.</p></section>
</HrmsLayout></template>
